package com.example.editor.recovery.continuity;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import org.springframework.stereotype.Service;
import com.example.editor.recovery.HydraRecoveryBackupManifest;
import com.example.editor.recovery.HydraRecoveryDrillReport;
import com.example.editor.recovery.HydraRecoveryDrillRequest;
import com.example.editor.recovery.HydraRecoveryService;
import com.example.editor.persistence.support.HydraPersistenceSupport;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.ObjectWriter;
import tools.jackson.databind.SerializationFeature;

/** BE measurable, local-first continuity plans over AZ backups and drills. */
@Service
public class HydraContinuityService {
    private final HydraRecoveryService recovery; private final HydraContinuityProperties properties;
    private final ObjectMapper mapper; private final ObjectWriter writer;
    /** Descripción: Inicializa una instancia de HydraContinuityService con sus dependencias y datos de entrada. Entradas: recovery: dato de entrada necesario para la operación; properties: configuración que gobierna el comportamiento; mapper: componente de conversión utilizado durante el procesamiento. Salida: deja la instancia inicializada y lista para su uso. */ public HydraContinuityService(HydraRecoveryService recovery,HydraContinuityProperties properties,ObjectMapper mapper){this.recovery=recovery;this.properties=properties;this.mapper=mapper;this.writer=mapper.writer(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS);}
    public synchronized HydraContinuityPlan save(HydraContinuityPlan plan){if(plan==null)throw new IllegalArgumentException("Continuity plan is required");HydraContinuityPlan safe=new HydraContinuityPlan(HydraPersistenceSupport.safeId(plan.planId(),"planId"),plan.name(),plan.enabled(),plan.rpoMinutes(),plan.rtoSeconds(),plan.retentionCount(),plan.drillCadenceDays(),plan.simulateCorruption(),plan.annotations(),Instant.now());write(planPath(safe.planId()),safe);HydraPersistenceSupport.trim(plansRoot(),properties.getMaximumPlans());return safe;}
    /** Descripción: Ejecuta la operación «plans» correspondiente a la responsabilidad de HydraContinuityService. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public List<HydraContinuityPlan> plans(){return readAll(plansRoot(),HydraContinuityPlan.class).stream().sorted(Comparator.comparing(HydraContinuityPlan::planId)).toList();}
    /** Descripción: Ejecuta la operación «duePlans» correspondiente a la responsabilidad de HydraContinuityService. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public List<HydraContinuityPlan> duePlans(){Instant now=Instant.now();return plans().stream().filter(HydraContinuityPlan::enabled).filter(plan->{HydraContinuityRunReport latest=reports().stream().filter(value->value.planId().equals(plan.planId())).findFirst().orElse(null);return latest==null||latest.completedAt().plus(Duration.ofDays(plan.drillCadenceDays())).isBefore(now);}).toList();}
    public synchronized HydraContinuityRunReport run(HydraContinuityRunRequest request){if(request==null)throw new IllegalArgumentException("Continuity run request is required");HydraContinuityPlan plan=findPlan(request.planId());if(!plan.enabled())throw new IllegalStateException("Continuity plan is disabled");List<HydraRecoveryBackupManifest> before=recovery.backups();HydraRecoveryBackupManifest backup=request.createFreshBackup()||before.isEmpty()?recovery.backup():before.getFirst();HydraRecoveryBackupManifest previous=before.stream().filter(value->!value.backupId().equals(backup.backupId())).findFirst().orElse(null);long rpo=previous==null?0:Math.max(0,Duration.between(previous.createdAt(),backup.createdAt()).toMinutes());long started=System.nanoTime();HydraRecoveryDrillReport drill=recovery.drill(new HydraRecoveryDrillRequest(backup.backupId(),plan.simulateCorruption(),true));long rto=Math.max(0,(System.nanoTime()-started)/1_000_000L);List<String> rotated=recovery.retain(plan.retentionCount());boolean rpoSatisfied=rpo<=plan.rpoMinutes(),rtoSatisfied=rto<=plan.rtoSeconds()*1000L;List<String> diagnostics=new ArrayList<>(drill.diagnostics());if(!rpoSatisfied)diagnostics.add("Measured RPO exceeds the configured objective");if(!rtoSatisfied)diagnostics.add("Measured RTO exceeds the configured objective");boolean passed=drill.passed()&&rpoSatisfied&&rtoSatisfied;String evidence=HydraPersistenceSupport.fingerprint(writer,java.util.Map.of("planId",plan.planId(),"backupId",backup.backupId(),"rpo",rpo,"rto",rto,"passed",passed));HydraContinuityRunReport report=new HydraContinuityRunReport("continuity-"+evidence.substring(0,20),plan.planId(),backup.backupId(),passed,rpo,rto,rpoSatisfied,rtoSatisfied,rotated,diagnostics,Instant.now());write(reportPath(report.runId()),report);HydraPersistenceSupport.trim(reportsRoot(),properties.getMaximumReports());return report;}
    /** Descripción: Ejecuta la operación «compare» correspondiente a la responsabilidad de HydraContinuityService. Entradas: baselineId: identificador que delimita el recurso objetivo; candidateId: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ public HydraContinuityComparison compare(String baselineId,String candidateId){HydraContinuityRunReport baseline=findReport(baselineId),candidate=findReport(candidateId);long rpo=candidate.measuredRpoMinutes()-baseline.measuredRpoMinutes(),rto=candidate.measuredRtoMillis()-baseline.measuredRtoMillis();boolean improved=rpo<=0&&rto<=0&&(rpo<0||rto<0);return new HydraContinuityComparison(baseline.runId(),candidate.runId(),rpo,rto,improved,improved?"Candidate recovery objectives improved or remained stable":"Candidate recovery evidence regressed in at least one objective");}
    /** Descripción: Ejecuta la operación «reports» correspondiente a la responsabilidad de HydraContinuityService. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public List<HydraContinuityRunReport> reports(){return readAll(reportsRoot(),HydraContinuityRunReport.class).stream().sorted(Comparator.comparing(HydraContinuityRunReport::completedAt).reversed()).toList();}
    /** Descripción: Obtiene la información correspondiente a «findPlan» dentro de HydraContinuityService. Entradas: id: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ public HydraContinuityPlan findPlan(String id){String safe=HydraPersistenceSupport.safeId(id,"planId");return plans().stream().filter(value->value.planId().equals(safe)).findFirst().orElseThrow(()->new IllegalArgumentException("Continuity plan was not found"));}
    /** Descripción: Obtiene la información correspondiente a «findReport» dentro de HydraContinuityService. Entradas: id: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ public HydraContinuityRunReport findReport(String id){String safe=HydraPersistenceSupport.safeId(id,"runId");return reports().stream().filter(value->value.runId().equals(safe)).findFirst().orElseThrow(()->new IllegalArgumentException("Continuity report was not found"));}
    /** Descripción: Obtiene la información correspondiente a «readAll» dentro de HydraContinuityService. Entradas: root: ruta o ubicación utilizada por la operación; type: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private <T> List<T> readAll(Path root,Class<T> type){List<T> result=new ArrayList<>();for(Path path:HydraPersistenceSupport.jsonFiles(root))try{result.add(mapper.readValue(com.example.editor.io.BoundedIo.readInternal(path),type));}catch(Exception ignored){com.example.editor.observability.HydraBestEffortDiagnostics.record("com/example/editor/recovery/continuity/HydraContinuityService.java",ignored);}return result;}
    /** Descripción: Actualiza el estado gestionado por HydraContinuityService mediante la operación «write». Entradas: path: ruta o ubicación utilizada por la operación; value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void write(Path path,Object value){try{HydraPersistenceSupport.atomicWrite(path,writer.writeValueAsBytes(value));}catch(Exception exception){throw new IllegalStateException("Could not persist continuity evidence",exception);}}
    /** Descripción: Ejecuta la operación «plansRoot» correspondiente a la responsabilidad de HydraContinuityService. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ private Path plansRoot(){return properties.getStorageRoot().resolve("plans");} /** Descripción: Ejecuta la operación «reportsRoot» correspondiente a la responsabilidad de HydraContinuityService. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ private Path reportsRoot(){return properties.getStorageRoot().resolve("reports");}
    /** Descripción: Ejecuta la operación «planPath» correspondiente a la responsabilidad de HydraContinuityService. Entradas: id: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ private Path planPath(String id){return plansRoot().resolve(id+".json");} /** Descripción: Ejecuta la operación «reportPath» correspondiente a la responsabilidad de HydraContinuityService. Entradas: id: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ private Path reportPath(String id){return reportsRoot().resolve(id+".json");}
}
